import{c as r,Q as o,j as e,m as d}from"./chunks/framework.rWdQudnF.js";const c=JSON.parse('{"title":"架构师-备考 综合知识-系统工程-电子政务商务","description":"","frontmatter":{"title":"架构师-备考 综合知识-系统工程-电子政务商务"},"headers":[],"relativePath":"综合知识/系统工程/电子政务商务.md","filePath":"综合知识/系统工程/电子政务商务.md","lastUpdated":null}'),a={name:"综合知识/系统工程/电子政务商务.md"};function n(s,t,l,h,i,p){return o(),e("div",null,[...t[0]||(t[0]=[d('<h3 id="电子政务概述" tabindex="-1">电子政务概述 <a class="header-anchor" href="#电子政务概述" aria-label="Permalink to &quot;电子政务概述&quot;">​</a></h3><blockquote><p>电子政务是对现有政府形态的改造，利用信息技术将管理和服务职能集成，在网络上实现政府组织结构和工作流程优化重组。</p></blockquote><p><strong>3 类行为主体：</strong> 政府、企（事）业单位、居民（公民）。</p><p><strong>政府业务活动围绕这三类主体展开，形成 5 种不同又相互关联的领域。</strong></p><hr><h3 id="电子政务-4-种模式" tabindex="-1">电子政务 4 种模式 <a class="header-anchor" href="#电子政务-4-种模式" aria-label="Permalink to &quot;电子政务 4 种模式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式</th><th>全称</th><th>说明</th><th>典型示例</th></tr></thead><tbody><tr><td><strong>G2G</strong></td><td>政府→政府</td><td>政府内部/政府间业务</td><td>人口信息采集处理利用、户籍管理</td></tr><tr><td><strong>G2B</strong></td><td>政府→企（事）业单位</td><td>政府对企业服务</td><td>营业执照颁发、政府工程投标</td></tr><tr><td><strong>G2C</strong></td><td>政府→居民</td><td>政府对公民服务</td><td>社保查询、个税申报</td></tr><tr><td><strong>G2E</strong></td><td>政府→公务员</td><td>政府内部员工管理</td><td>人事管理、培训</td></tr></tbody></table><blockquote><p>⚠️ 电子政务主要应用模式中<strong>不包括</strong> G2C（Government To Customer），正确的是 G2C（Government To Citizen，政府对公民）。</p></blockquote><blockquote><p>辨析口诀：<strong>人口/户籍 → G2G；营业执照/招标 → G2B；社保/个税 → G2C。</strong></p></blockquote><hr><h3 id="电子商务" tabindex="-1">电子商务 <a class="header-anchor" href="#电子商务" aria-label="Permalink to &quot;电子商务&quot;">​</a></h3><p><strong>参与实体</strong>：客户、商户、银行、认证中心。</p><p><strong>常见模式</strong>：B2B（企业间）、B2C（企业对消费者）、C2C（消费者间）、O2O（线上到线下）。</p>',13)])])}const g=r(a,[["render",n]]);export{c as __pageData,g as default};
